# Browser Module 2 HTML report writers.
#
# These package-local writers preserve the visual design of the original
# benchmark HTML reports while avoiding runtime dependencies on dev/benchmark.

.module2_report_browser_html_escape <- function(x) {
    x <- as.character(x)
    x <- gsub("&", "&amp;", x, fixed = TRUE)
    x <- gsub("<", "&lt;", x, fixed = TRUE)
    x <- gsub(">", "&gt;", x, fixed = TRUE)
    x <- gsub("\"", "&quot;", x, fixed = TRUE)
    x
}

.module2_report_browser_network_payload <- function(nodes, edges, seed_tf, tf_only = FALSE) {
    from <- to <- edge_score <- abs_edge_score <- node_id <- NULL
    node_type <- is_target_gene <- shared_targets <- is_seed_tf <- NULL
    display_size <- edge_r <- node_role <- perturbation_log2fc <- NULL
    strict_mean_expression <- edge_class <- n_supporting_links <- best_peak_ID <- NULL
    node_dt <- data.table::copy(nodes)
    edge_dt <- data.table::copy(edges)
    edge_dt[, `:=`(from = toupper(as.character(from)), to = toupper(as.character(to)), edge_score = suppressWarnings(as.numeric(edge_score)), abs_edge_score = suppressWarnings(as.numeric(abs_edge_score)))]
    if (isTRUE(tf_only)) {
        tf_ids <- node_dt[node_type == "TF", node_id]
        edge_dt <- edge_dt[from %chin% tf_ids & to %chin% tf_ids]
    }
    if (!nrow(edge_dt)) {
        return(list(nodes = data.table(), edges = data.table()))
    }
    keep_nodes <- unique(c(edge_dt$from, edge_dt$to))
    node_dt <- node_dt[node_id %chin% keep_nodes]
    selected_targets <- unique(nodes[is_target_gene == TRUE, node_id])
    shared_dt <- edge_dt[to %chin% selected_targets, .(shared_targets = uniqueN(to)), by = from]
    data.table::setnames(shared_dt, "from", "node_id")
    node_dt <- merge(node_dt, shared_dt, by = "node_id", all.x = TRUE, sort = FALSE)
    node_dt[is.na(shared_targets), `:=`(shared_targets, 0L)]
    node_dt[is_seed_tf == TRUE, `:=`(shared_targets, max(shared_targets, length(selected_targets), na.rm = TRUE))]
    node_dt[, `:=`(display_size, fifelse(node_type == "TF", pmax(1, shared_targets), 1))]
    data.table::setorder(node_dt, -is_seed_tf, node_type, node_id)
    edge_dt[, `:=`(edge_r, abs_edge_score)]
    edge_dt[!is.finite(edge_r), `:=`(edge_r, 0)]
    list(nodes = node_dt[, .(id = node_id, node_type, node_role, is_seed_tf, is_target_gene, shared_targets, display_size, perturbation_log2fc, strict_mean_expression)], edges = edge_dt[, .(from, to, edge_class, edge_score, edge_r, n_supporting_links, best_peak_ID)])
}

