.module2_report_browser_ensure_dir <- function(path) {
    dir.create(path, recursive = TRUE, showWarnings = FALSE)
    if (!dir.exists(path)) {
        .log_abort(sprintf("Failed to create directory: %s", path))
    }
    path
}

.module2_report_browser_norm_gene <- function(x) {
    x <- toupper(trimws(as.character(x)))
    x[is.na(x)] <- ""
    x
}

.module2_report_browser_prepare_rna_condition_table <- function(rna_dt, comparison_dt = NULL, metadata_path = NULL) {
    id <- name <- NULL
    if (!nrow(rna_dt)) 
        return(rna_dt)
    if (!is.null(comparison_dt) && all(c("cond1_label", "cond2_label") %chin% names(comparison_dt))) {
        needed <- unique(c(comparison_dt$cond1_label, comparison_dt$cond2_label))
        if (all(needed %chin% names(rna_dt))) 
            return(rna_dt)
    }
    if (is.null(metadata_path) || !file.exists(metadata_path)) 
        return(rna_dt)
    meta_dt <- data.table::fread(metadata_path, showProgress = FALSE)
    if (!all(c("id", "name") %chin% names(meta_dt))) 
        return(rna_dt)
    meta_dt <- meta_dt[id %chin% names(rna_dt) & !is.na(name) & nzchar(name)]
    if (!nrow(meta_dt)) 
        return(rna_dt)
    gene_cols <- intersect(c("ensembl_gene_id", "HGNC"), names(rna_dt))
    out <- data.table::copy(rna_dt[, gene_cols, with = FALSE])
    for (condition_name in unique(meta_dt$name)) {
        ids <- meta_dt[name == condition_name, id]
        ids <- intersect(ids, names(rna_dt))
        if (!length(ids)) 
            next
        out[, `:=`((condition_name), rowMeans(rna_dt[, ids, with = FALSE], na.rm = TRUE))]
    }
    out
}

.module2_report_browser_browser_payload_to_columnar <- function(x) {
    x <- as.data.frame(x, stringsAsFactors = FALSE)
    list(columns = names(x), data = unname(lapply(x, unname)))
}

.module2_report_browser_encode_browser_json_deflate_base64 <- function(x) {
    json <- jsonlite::toJSON(x, dataframe = "rows", auto_unbox = TRUE, null = "null")
    gsub("[\r\n]", "", jsonlite::base64_enc(memCompress(charToRaw(as.character(json)), "gzip")))
}

.module2_report_browser_png_file_to_data_uri <- function(path) {
    if (!file.exists(path)) 
        return(NA_character_)
    size <- file.info(path)$size[[1L]]
    if (!is.finite(size) || size <= 0) 
        return(NA_character_)
    raw_png <- readBin(path, what = "raw", n = size)
    paste0("data:image/png;base64,", gsub("[\r\n]", "", jsonlite::base64_enc(raw_png)))
}

.module2_report_browser_write_condition_direct_tf_tf_k_index <- function(edge_dt, out_dir, title_prefix, k_label, max_edges_per_cluster = 250L, max_nodes_per_cluster = Inf, heatmap_dt = data.table(), network_label = "Direct TF network", page_label = "direct TF-TF", edge_label = "direct TF-to-TF edges", out_suffix = "direct_tf_tf_network_browser") {
    from_cluster <- to_cluster <- direct_tf_cluster_pair <- NULL
    col_cluster_label <- row_cluster_label <- tf_expr <- NULL
    n_supporting_peaks <- mean_condition_fp_score <- NULL
    mean_fp_target_rna_r <- mean_tf_expression_target_r <- NULL
    edge_score <- from <- to <- from_expr <- to_expr <- NULL
    heatmap_png <- heatmap_image <- condition <- tf <- NULL
    if (!nrow(edge_dt)) 
        return(NA_character_)
    out_dir <- .module2_report_browser_ensure_dir(out_dir)
    dt <- data.table::copy(edge_dt)
    dt <- dt[from_cluster != "T00" & to_cluster != "T00"]
    if (!nrow(dt)) 
        return(NA_character_)
    dt[, `:=`(row_cluster_label = sub("^T", "R", as.character(from_cluster)), col_cluster_label = sub("^T", "C", as.character(to_cluster)))]
    dt[, `:=`(direct_tf_cluster_pair, paste(col_cluster_label, row_cluster_label, sep = "-"))]
    base_dir <- dirname(dirname(dirname(dirname(out_dir))))
    rna_path <- Sys.getenv("CRAFTGRN_TFRC_RNA_FILTERED_CSV", unset = file.path(base_dir, "data", "rna_strict.csv"))
    metadata_path <- Sys.getenv("CRAFTGRN_TFRC_SAMPLE_METADATA_CSV", unset = file.path(base_dir, "data", "sample_metadata_strict.csv"))
    expr_long <- data.table()
    if (file.exists(rna_path)) {
        rna_dt <- data.table::fread(rna_path, showProgress = FALSE)
        rna_dt <- .module2_report_browser_prepare_rna_condition_table(rna_dt, metadata_path = metadata_path)
        gene_col <- if ("HGNC" %chin% names(rna_dt)) 
            "HGNC"
        else if ("gene_symbol" %chin% names(rna_dt)) 
            "gene_symbol"
        else if ("ensembl_gene_id" %chin% names(rna_dt)) 
            "ensembl_gene_id"
        else NA_character_
        condition_cols <- intersect(unique(dt$condition), names(rna_dt))
        if (!is.na(gene_col) && length(condition_cols)) {
            expr_long <- data.table::melt(rna_dt[, c(gene_col, condition_cols), with = FALSE], id.vars = gene_col, variable.name = "condition", value.name = "tf_expr")
            data.table::setnames(expr_long, gene_col, "tf")
            expr_long[, `:=`(tf = .module2_report_browser_norm_gene(tf), condition = as.character(condition), tf_expr = suppressWarnings(as.numeric(tf_expr)))]
            expr_long <- unique(expr_long[nzchar(tf), .(condition, tf, tf_expr)])
        }
    }
    if (nrow(expr_long)) {
        dt <- merge(dt, expr_long, by.x = c("condition", "from"), by.y = c("condition", "tf"), all.x = TRUE, sort = FALSE)
        data.table::setnames(dt, "tf_expr", "from_expr")
        dt <- merge(dt, expr_long, by.x = c("condition", "to"), by.y = c("condition", "tf"), all.x = TRUE, sort = FALSE)
        data.table::setnames(dt, "tf_expr", "to_expr")
    }
    else {
        dt[, `:=`(from_expr = NA_real_, to_expr = NA_real_)]
    }
    if (!"n_supporting_peaks" %chin% names(dt)) 
        dt[, `:=`(n_supporting_peaks, NA_integer_)]
    if (!"mean_condition_fp_score" %chin% names(dt)) 
        dt[, `:=`(mean_condition_fp_score, NA_real_)]
    if (!"mean_fp_target_rna_r" %chin% names(dt)) 
        dt[, `:=`(mean_fp_target_rna_r, NA_real_)]
    if (!"mean_tf_expression_target_r" %chin% names(dt)) 
        dt[, `:=`(mean_tf_expression_target_r, NA_real_)]
    data.table::setorder(dt, condition, to_cluster, from_cluster, -edge_score, from, to)
    html_escape <- function(x) {
        x <- as.character(x)
        x <- gsub("&", "&amp;", x, fixed = TRUE)
        x <- gsub("<", "&lt;", x, fixed = TRUE)
        x <- gsub(">", "&gt;", x, fixed = TRUE)
        x <- gsub("\"", "&quot;", x, fixed = TRUE)
